using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;
using System.Collections.Generic;
public static class IslandBlockoutV01 {
 const string Dir="Assets/Island_Blockout_V01";
 static Vector2[] main={new(-180,-205),new(-165,-155),new(-115,-120),new(-60,-130),new(-10,-95),new(35,-65),new(25,-15),new(40,35),new(90,45),new(145,60),new(165,115),new(205,155)};
 static Vector2[][] routes={main,new[]{new Vector2(-115,-120),new Vector2(-155,-50),new Vector2(-130,25),new Vector2(-75,80)},new[]{new Vector2(90,45),new Vector2(110,-20),new Vector2(160,-65),new Vector2(110,-130),new Vector2(35,-65)},new[]{new Vector2(40,35),new Vector2(15,65)}};
 static float G(float x,float z,float cx,float cz,float sx,float sz)=>Mathf.Exp(-((x-cx)*(x-cx)/(sx*sx)+(z-cz)*(z-cz)/(sz*sz)));
 static float Raw(float x,float z){float a=Mathf.Atan2(z,x);float r=255+28*Mathf.Sin(a*3+.5f)+18*Mathf.Cos(a*5)-45*G(x,z,-30,-230,65,70);float coast=(r-Mathf.Sqrt(x*x+z*z))*.35f;float h=9+12*Mathf.PerlinNoise(x*.011f+12,z*.011f+12)+95*G(x,z,0,110,85,95)+78*G(x,z,205,155,60,65)+25*G(x,z,140,20,100,110);return Mathf.Max(-18,Mathf.Min(coast,h));}
 static float H(float x,float z){float h=Raw(x,z);foreach(var route in routes)for(int i=1;i<route.Length;i++){var v=route[i]-route[i-1];float t=Mathf.Clamp01(Vector2.Dot(new Vector2(x,z)-route[i-1],v)/v.sqrMagnitude);float d=Vector2.Distance(new Vector2(x,z),route[i-1]+v*t);float grade=Mathf.Lerp(Raw(route[i-1].x,route[i-1].y),Raw(route[i].x,route[i].y),t);h=Mathf.Lerp(h,grade,1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(5,15,d)));}return h;}
 static Material Mat(string n,Color c){var m=new Material(Shader.Find("Standard"));m.color=c;AssetDatabase.CreateAsset(m,Dir+"/"+n+".mat");return m;}
 static Vector3 P(Vector2 p)=>new(p.x,H(p.x,p.y)+1,p.y);
 [MenuItem("Island/Build Blockout V01")]
 public static void Build(){Directory.CreateDirectory(Dir);Directory.CreateDirectory("Docs/Island_Blockout_V01");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
 var td=new TerrainData{heightmapResolution=513,size=new Vector3(720,180,720),alphamapResolution=256};var hs=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++)hs[z,x]=(H(x/512f*720-360,z/512f*720-360)+25)/180;td.SetHeights(0,0,hs);
 Color[] colors={new(.88f,.75f,.46f),new(.51f,.68f,.34f),new(.25f,.46f,.27f),new(.5f,.5f,.49f)};var layers=new TerrainLayer[4];for(int i=0;i<4;i++){var tex=new Texture2D(2,2);tex.SetPixels(new[]{colors[i],colors[i],colors[i],colors[i]});tex.Apply();AssetDatabase.CreateAsset(tex,Dir+"/Color"+i+".asset");layers[i]=new TerrainLayer{diffuseTexture=tex};AssetDatabase.CreateAsset(layers[i],Dir+"/Layer"+i+".asset");}td.terrainLayers=layers;var am=new float[256,256,4];for(int z=0;z<256;z++)for(int x=0;x<256;x++){float xx=x/255f*720-360,zz=z/255f*720-360,h=H(xx,zz);am[z,x,h<7?0:h>43?3:zz< -95?1:2]=1;}td.SetAlphamaps(0,0,am);AssetDatabase.CreateAsset(td,Dir+"/Terrain.asset");var terrain=Terrain.CreateTerrainGameObject(td);terrain.GetComponent<Terrain>().materialTemplate=new Material(Shader.Find("Nature/Terrain/Standard"));terrain.name="Continuous island terrain (metres)";terrain.transform.position=new(-360,-25,-360);
 var sea=GameObject.CreatePrimitive(PrimitiveType.Plane);sea.name="Ocean 20km";sea.transform.localScale=new(2000,1,2000);sea.GetComponent<Renderer>().sharedMaterial=Mat("Ocean",new(.12f,.52f,.65f));
 var orange=Mat("Main route",new(1,.36f,.12f));var white=Mat("Branches",new(.9f,.95f,.76f));for(int j=0;j<routes.Length;j++){var line=new GameObject(j==0?"MAIN ROUTE":"Exploration branch "+j).AddComponent<LineRenderer>();line.sharedMaterial=j==0?orange:white;line.widthMultiplier=j==0?3:1.6f;var pts=new List<Vector3>();for(int i=1;i<routes[j].Length;i++)for(int k=0;k<30;k++)pts.Add(P(Vector2.Lerp(routes[j][i-1],routes[j][i],k/30f)));pts.Add(P(routes[j][^1]));line.positionCount=pts.Count;line.SetPositions(pts.ToArray());}
 var river=new GameObject("River valley reservation").AddComponent<LineRenderer>();river.sharedMaterial=Mat("River",Color.cyan);river.widthMultiplier=7;var rp=new List<Vector3>();for(int i=0;i<=100;i++){float z=-235+i*2.8f;rp.Add(P(new Vector2(15+25*Mathf.Sin(z*.026f),z)) +Vector3.up*.4f);}river.positionCount=rp.Count;river.SetPositions(rp.ToArray());
 string[] names={"01 Beach / wreck reserve","02 Coastal forest","03 Central forest","04 River valley","05 Mountain","06 Cave reserve","07 Ruins reserve","08 Lighthouse reserve"};Vector2[] centers={new(-180,-205),new(-145,-130),new(-100,-25),new(25,-85),new(0,110),new(15,65),new(115,5),new(205,155)};for(int i=0;i<names.Length;i++){var go=new GameObject(names[i]);go.transform.position=P(centers[i])+Vector3.up*5;var text=go.AddComponent<TextMesh>();text.text=names[i];text.characterSize=2.5f;text.fontSize=48;text.anchor=TextAnchor.MiddleCenter;go.transform.rotation=Quaternion.Euler(90,0,0);}
 var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(45,-35,0);sun.intensity=1.2f;RenderSettings.ambientLight=new Color(.65f,.65f,.65f);
 var cam=new GameObject("Overview angled").AddComponent<Camera>();cam.tag="MainCamera";cam.farClipPlane=15000;cam.transform.position=new(650,700,-820);cam.transform.LookAt(new Vector3(0,10,0));cam.orthographic=true;cam.orthographicSize=370;Shot(cam,"Overview");var top=new GameObject("Top view").AddComponent<Camera>();top.orthographic=true;top.orthographicSize=355;top.farClipPlane=15000;top.transform.position=new(0,1000,0);top.transform.rotation=Quaternion.Euler(90,0,0);Shot(top,"Top");top.enabled=false;
 EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),"Assets/Scenes/Island_Blockout_V01.unity");AssetDatabase.SaveAssets();Debug.Log("ISLAND_BLOCKOUT_COMPLETE");}
 static void Shot(Camera c,string name){var rt=new RenderTexture(1600,1200,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1600,1200,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,1200),0,0);t.Apply();File.WriteAllBytes("Docs/Island_Blockout_V01/"+name+".png",t.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;Object.DestroyImmediate(rt);Object.DestroyImmediate(t);}
}

